SELECT 
FROM TBL_INSTRUMENT_BASIC_INFO
WHERE ORGID = #{orgId}

    AND INSTRUMENTNO LIKE CONCAT('%', #{instrumentNo}, '%')


    AND INSTRUMENTTYPE = #{instrumentType}


    AND INSTRUMENTSTATUS = #{instrumentStatus}


    AND ISSUER LIKE CONCAT('%', #{issuer}, '%')


    AND PAYEE LIKE CONCAT('%', #{payee}, '%')


    AND MATURITYDATE >= #{maturityDateStart}


    AND MATURITYDATE <= #{maturityDateEnd}

ORDER BY CREATETIME DESC

SELECT 
FROM TBL_INSTRUMENT_BASIC_INFO
WHERE INSTRUMENTNO = #{instrumentNo} AND ORGID = #{orgId}

SELECT COALESCE(SUM(FACEAMOUNT), 0)
FROM TBL_INSTRUMENT_BASIC_INFO
WHERE ORGID = #{orgId}

    AND INSTRUMENTSTATUS = #{instrumentStatus}

SELECT 
FROM TBL_INSTRUMENT_BASIC_INFO
WHERE ORGID = #{orgId}


        AND ISSUEDATE BETWEEN #{startDate} AND #{endDate}


        AND MATURITYDATE BETWEEN #{startDate} AND #{endDate}


        AND CREATETIME BETWEEN #{startDate} AND #{endDate}


ORDER BY CREATETIME DESC

SELECT 'BASIC_INFO' as operationType, CREATETIME as operationTime, CREATEUSER as operationUser, CONCAT('创建票据: ', INSTRUMENTNO) as operationDesc FROM TBL_INSTRUMENT_BASIC_INFO WHERE INSTRUMENTID = #{instrumentId}
UNION ALL
SELECT 'STATUS_CHANGE' as operationType, UPDATETIME as operationTime, UPDATEUSER as operationUser, CONCAT('状态变更: ', INSTRUMENTSTATUS) as operationDesc FROM TBL_INSTRUMENT_BASIC_INFO WHERE INSTRUMENTID = #{instrumentId}
ORDER BY operationTime DESC

