SELECT
INSTRUMENTTYPE as groupKey,
INSTRUMENTSTATUS as groupKey,
CURRENCYCODE as groupKey,
DATE_FORMAT(CREATETIME, '%Y-%m') as groupKey,
COUNT(*) as count, SUM(FACEAMOUNT) as totalAmount, AVG(FACEAMOUNT) as avgAmount FROM TBL_INSTRUMENT_BASIC_INFO WHERE ORGID = #{orgId}
AND DATE(CREATETIME) >= #{startDate}
AND DATE(CREATETIME) <= #{endDate}
GROUP BY groupKey ORDER BY count DESC

SELECT COUNT(*)
FROM TBL_INSTRUMENT_BASIC_INFO
WHERE INSTRUMENTNO = #{instrumentNo}
AND ORGID = #{orgId}

    AND INSTRUMENTID != #{excludeId}
